-- Extra columns to match the UI
alter table public.memories add column if not exists when_label text;
alter table public.insights add column if not exists when_label text;
alter table public.insights add column if not exists at_label text;
alter table public.connectors add column if not exists scopes text[];
alter table public.connectors add column if not exists official boolean not null default false;
alter table public.connectors add column if not exists last_sync_label text;
alter table public.messages add column if not exists at_label text;

create or replace function public.seed_workspace(ws uuid, uid uuid)
returns void language plpgsql security definer set search_path=public as $fn$
declare conv_design uuid;
begin
end $fn$;

create or replace function public.handle_new_user()
returns trigger language plpgsql security definer set search_path=public as $$
declare ws uuid;
begin
  values (new.id, coalesce(new.raw_user_meta_data ->> 'name', split_part(new.email, '@', 1)), new.email)
  on conflict (id) do nothing;
  values (coalesce(new.raw_user_meta_data ->> 'name', 'My') || '''s workspace', new.id)
  returning id into ws;
  perform public.seed_workspace(ws, new.id);
  return new;
end $$;